const DOMAINS = [
  { key: "ai", label: "Intelligence Artificielle", rows: [...AI, ...AI_RESEARCH] },
  { key: "agents", label: "AI Agents", rows: [...AGENTS, ...AGENTS_RESEARCH] },
  { key: "devops", label: "DevOps", rows: [...DEVOPS, ...DEVOPS_RESEARCH] },
  { key: "cyber", label: "Cybersécurité", rows: [...CYBER, ...CYBER_RESEARCH] },
  { key: "data", label: "Data Analysis", rows: [...DATA, ...DATA_RESEARCH] },
];

function typeFromLevel(level) {
  if (level === "Débutant") return { type: "PFE Licence", months: 4 };
  if (level === "Recherche") return { type: "PFE de recherche", months: 6 };
  return { type: "PFE Ingénieur ou Master", months: 6 };
}

const LEVEL_CODE = {
  "Débutant": "beginner",
  "Intermédiaire": "intermediate",
  "Avancé": "advanced",
  "Recherche": "research",
};

let counter = 0;
export const SUJETS = DOMAINS.flatMap((d) =>
  d.rows.map((r) => {
    counter += 1;
    return {
      id: "PFE-" + String(counter).padStart(3, "0"),
      domain: d.key,
      domainLabel: d.label,
      title: r[0],
      stack: r[1],
      level: LEVEL_CODE[r[2]] || "intermediate",
      ...typeFromLevel(r[2]),
    };
  })
);

export const DOMAIN_LIST = DOMAINS.map((d) => ({ key: d.key, label: d.label, count: d.rows.length }));
export const TYPES = ["PFE Licence", "PFE Ingénieur ou Master", "PFE de recherche"];
